import{_ as d,o as t,c as o,a0 as c}from"./chunks/framework.BZ80FTt7.js";const u=JSON.parse('{"title":"2026-07-01：复习 C++ STL 和刷题","description":"","frontmatter":{},"headers":[],"relativePath":"blog/2026-07-01-cpp-stl.md","filePath":"blog/2026-07-01-cpp-stl.md"}'),a={name:"blog/2026-07-01-cpp-stl.md"};function l(r,e,i,n,s,p){return t(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="_2026-07-01-复习-c-stl-和刷题" tabindex="-1">2026-07-01：复习 C++ STL 和刷题 <a class="header-anchor" href="#_2026-07-01-复习-c-stl-和刷题" aria-label="Permalink to &quot;2026-07-01：复习 C++ STL 和刷题&quot;">​</a></h1><p>今天按照桌面上的 <code>C++算法与数据结构完整学习路径.md</code> 复习了 C++ 算法与数据结构学习路径里的第 1 阶段内容，重点放在 STL。</p><p>这次复习的目标不是把所有接口都背下来，而是重新把常用容器、常用算法和刷题时的选择思路串起来。STL 是后面学数据结构和算法题的基础，很多题写得快不快，关键就在于能不能选对容器、知道对应操作的复杂度。</p><h2 id="今天复习的重点" tabindex="-1">今天复习的重点 <a class="header-anchor" href="#今天复习的重点" aria-label="Permalink to &quot;今天复习的重点&quot;">​</a></h2><h3 id="stl-容器" tabindex="-1">STL 容器 <a class="header-anchor" href="#stl-容器" aria-label="Permalink to &quot;STL 容器&quot;">​</a></h3><p>今天重新过了一遍常见容器的特点：</p><table tabindex="0"><thead><tr><th>容器</th><th>适合场景</th><th>需要注意的点</th></tr></thead><tbody><tr><td><code>vector</code></td><td>顺序存储、随机访问、动态数组</td><td>中间插入和删除是 O(n)</td></tr><tr><td><code>deque</code></td><td>两端插入删除</td><td>比 <code>vector</code> 更适合队列类操作</td></tr><tr><td><code>list</code></td><td>频繁插入删除</td><td>不支持随机访问</td></tr><tr><td><code>stack</code></td><td>后进先出</td><td>常用于括号匹配、单调栈</td></tr><tr><td><code>queue</code></td><td>先进先出</td><td>常用于 BFS</td></tr><tr><td><code>priority_queue</code></td><td>每次取最大或最小元素</td><td>本质是堆，操作是 O(log n)</td></tr><tr><td><code>set</code> / <code>map</code></td><td>有序集合、键值映射</td><td>底层红黑树，查找插入删除 O(log n)</td></tr><tr><td><code>unordered_set</code> / <code>unordered_map</code></td><td>快速查找和计数</td><td>平均 O(1)，但不保证有序</td></tr></tbody></table><p>今天比较明确的一点是：刷题时不要只凭习惯用 <code>vector</code>。如果题目核心是查找、去重、计数、维护顺序、取最值，通常应该先想对应的 STL 容器。</p><h2 id="stl-算法" tabindex="-1">STL 算法 <a class="header-anchor" href="#stl-算法" aria-label="Permalink to &quot;STL 算法&quot;">​</a></h2><p>今天也复习了 <code>&lt;algorithm&gt;</code> 和 <code>&lt;numeric&gt;</code> 里常用的函数：</p><ul><li><code>sort</code>：排序，最常用</li><li><code>stable_sort</code>：稳定排序</li><li><code>lower_bound</code> / <code>upper_bound</code>：二分查找边界</li><li><code>binary_search</code>：判断是否存在</li><li><code>reverse</code>：翻转区间</li><li><code>rotate</code>：旋转区间</li><li><code>max_element</code> / <code>min_element</code>：找最大最小元素</li><li><code>accumulate</code>：求和或累积计算</li><li><code>unique</code>：配合排序做去重</li></ul><p>今天最大的提醒是：很多题不需要自己手写完整逻辑，先想标准库有没有现成算法。比如二分边界、求和、翻转、去重这些操作，用 STL 写出来更短，也更不容易出错。</p><h2 id="今天做题的体会" tabindex="-1">今天做题的体会 <a class="header-anchor" href="#今天做题的体会" aria-label="Permalink to &quot;今天做题的体会&quot;">​</a></h2><p>今天复习完 STL 后做了一些题，主要是在练习容器和算法的选择。</p><p>做题时比较明显的问题是：有些题一开始会下意识写朴素循环，写到一半才发现可以用 <code>map</code>、<code>set</code> 或 <code>sort + two pointers</code> 简化。之后刷题要刻意训练这个流程：</p><ol><li>先看题目需要维护什么信息。</li><li>判断是否需要顺序、去重、计数、快速查找、最大最小值。</li><li>再选择 <code>vector</code>、<code>set</code>、<code>map</code>、<code>unordered_map</code>、<code>queue</code>、<code>priority_queue</code> 等容器。</li><li>最后检查每一步复杂度是否能过。</li></ol><h2 id="今天的收获" tabindex="-1">今天的收获 <a class="header-anchor" href="#今天的收获" aria-label="Permalink to &quot;今天的收获&quot;">​</a></h2><p>今天把 STL 从“知道有这些东西”重新整理成了“刷题时怎么选”的思路。</p><p>现在对几个基础判断更清楚了：</p><ul><li>要随机访问和顺序遍历，优先想 <code>vector</code></li><li>要快速查找和计数，优先想 <code>unordered_map</code></li><li>要自动有序，优先想 <code>set</code> / <code>map</code></li><li>要先进先出，想 <code>queue</code></li><li>要后进先出，想 <code>stack</code></li><li>要动态维护最大值或最小值，想 <code>priority_queue</code></li><li>要排序、二分、去重，先想 <code>&lt;algorithm&gt;</code></li></ul><h2 id="接下来" tabindex="-1">接下来 <a class="header-anchor" href="#接下来" aria-label="Permalink to &quot;接下来&quot;">​</a></h2><ul><li>[ ] 继续做 STL 基础题，把容器选择练熟</li><li>[ ] 专门整理 <code>map</code>、<code>set</code>、<code>unordered_map</code> 的使用差别</li><li>[ ] 开始进入数组、字符串和基础递归题</li></ul><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h2><p>今天的重点不是 STL 语法，而是建立刷题时“根据问题选工具”的意识。后面做算法题，要让 STL 先成为默认工具箱。</p>',24)])])}const _=d(a,[["render",l]]);export{u as __pageData,_ as default};
